// signature = HMAC-SHA256(secret, `${ts}.${METHOD}.${pathAndQuery}.${rawBody}`)
const crypto = require('crypto');
const SECRET = $env.LENDLOOP_INBOUND_SIGNING_SECRET;
const BASE = ($env.LENDLOOP_CONVEX_SITE_URL || '').replace(/\/$/, '');
if (!SECRET || !BASE) throw new Error('LENDLOOP_INBOUND_SIGNING_SECRET and LENDLOOP_CONVEX_SITE_URL must be set');
function signed(method, pathAndQuery, body) {
  const rawBody = body === undefined ? '' : JSON.stringify(body);
  const ts = Math.floor(Date.now() / 1000).toString();
  const sig = crypto.createHmac('sha256', SECRET).update(`${ts}.${method}.${pathAndQuery}.${rawBody}`).digest('hex');
  return {
    url: BASE + pathAndQuery,
    rawBody,
    headers: { 'Content-Type': 'application/json', 'X-LendLoop-Timestamp': ts, 'X-LendLoop-Signature': `v1=${sig}` },
  };
}

// "Today" in the n8n instance timezone (GENERIC_TIMEZONE). Convex rejects
// dates more than a day away from its own clock.
const asOf = $now.toFormat('yyyy-MM-dd');
return [{ json: { asOf, ...signed('GET', `/automation/overdue-loans?asOf=${asOf}`) } }];

