// Shared signing helper (same scheme as convex/automation/signing.ts):
// signature = HMAC-SHA256(secret, `${ts}.${METHOD}.${pathAndQuery}.${rawBody}`)
const crypto = require('crypto');
const SECRET = $env.LENDLOOP_INBOUND_SIGNING_SECRET;
const BASE = ($env.LENDLOOP_CONVEX_SITE_URL || '').replace(/\/$/, '');
if (!SECRET || !BASE) throw new Error('LENDLOOP_INBOUND_SIGNING_SECRET and LENDLOOP_CONVEX_SITE_URL must be set');
function signed(method, pathAndQuery, body) {
  const rawBody = body === undefined ? '' : JSON.stringify(body);
  const ts = Math.floor(Date.now() / 1000).toString();
  const sig = crypto.createHmac('sha256', SECRET).update(`${ts}.${method}.${pathAndQuery}.${rawBody}`).digest('hex');
  return {
    url: BASE + pathAndQuery,
    rawBody,
    headers: { 'Content-Type': 'application/json', 'X-LendLoop-Timestamp': ts, 'X-LendLoop-Signature': `v1=${sig}` },
  };
}

// One write-back per reminder. Convex keys it on `${loanId}:${asOf}`, so a
// retried request or a re-run of this workflow can never duplicate it.
const loans = $('One item per loan').all();
const asOf = $('Sign: fetch overdue').first().json.asOf;
return $input.all().map((item, i) => {
  const loan = loans[item.pairedItem?.item ?? i].json;
  const failed = Boolean(item.json.error);
  const body = {
    loanId: loan.loanId,
    asOf,
    status: failed ? 'failed' : 'sent',
    channel: 'email',
    executionId: String($execution.id),
    ...(failed ? { error: String(item.json.error?.message ?? item.json.error).slice(0, 500) } : {}),
  };
  return { json: { loanId: loan.loanId, status: body.status, ...signed('POST', '/automation/reminders', body) } };
});

// Shared signing helper (same scheme as convex/automation/signing.ts):
// signature = HMAC-SHA256(secret, `${ts}.${METHOD}.${pathAndQuery}.${rawBody}`)
const crypto = require('crypto');
const SECRET = $env.LENDLOOP_INBOUND_SIGNING_SECRET;
const BASE = ($env.LENDLOOP_CONVEX_SITE_URL || '').replace(/\/$/, '');
if (!SECRET || !BASE) throw new Error('LENDLOOP_INBOUND_SIGNING_SECRET and LENDLOOP_CONVEX_SITE_URL must be set');
function signed(method, pathAndQuery, body) {
  const rawBody = body === undefined ? '' : JSON.stringify(body);
  const ts = Math.floor(Date.now() / 1000).toString();
  const sig = crypto.createHmac('sha256', SECRET).update(`${ts}.${method}.${pathAndQuery}.${rawBody}`).digest('hex');
  return {
    url: BASE + pathAndQuery,
    rawBody,
    headers: { 'Content-Type': 'application/json', 'X-LendLoop-Timestamp': ts, 'X-LendLoop-Signature': `v1=${sig}` },
  };
}

// Heartbeat for the Convex watchdog: always posted, even when nothing is
// overdue, so "the job silently stopped running" is detectable.
const fetched = $('Fetch overdue loans').first().json;
let results = [];
try { results = $('Sign write-back').all().map((i) => i.json.status); } catch { /* no overdue loans today */ }
const body = {
  executionId: String($execution.id),
  workflow: 'overdue-reminders',
  asOf: fetched.asOf,
  overdueCount: fetched.count,
  sent: results.filter((s) => s === 'sent').length,
  failed: results.filter((s) => s === 'failed').length,
};
return [{ json: { summary: body, ...signed('POST', '/automation/runs', body) } }];
